-- VibeCritic manually authored reference batch 0006.
-- Methodological material only; never treat these texts as factual evidence about reviewed works.
CREATE TABLE IF NOT EXISTS editorial_reference_articles (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, work_type TEXT NOT NULL CHECK (work_type IN ('all','movie','tv','game')), topic TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 50, summary TEXT NOT NULL, prompt_excerpt TEXT NOT NULL, body TEXT NOT NULL, authoring TEXT NOT NULL DEFAULT 'VibeCritic editorial framework', version INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)), created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_editorial_reference_select ON editorial_reference_articles(active, work_type, priority DESC);
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('game-player-agency','فاعلية اللاعب: الاختيار الذي يغيّر التجربة','game','agency',98,'اختبر هل تمنح اللعبة اللاعب قرارات ذات أثر، أم تكتفي بعرض اختيارات شكلية. اربط الحرية بالعواقب والأنظمة التي تستجيب للفعل.','ميّز بين عدد الخيارات وأثرها. اسأل: هل يغيّر القرار الموارد أو العلاقات أو المسار أو الاستراتيجية؟ هل تعرض اللعبة عواقب مفهومة؟ لا تصف الاختيار بأنه عميق لمجرد وجود فروع كثيرة.','فاعلية اللاعب ليست مرادفاً لعدد الأزرار أو النهايات أو الخيارات الحوارية. الاختيار يصبح ذا معنى عندما يغيّر حالة النظام أو يفرض مفاضلة لها ثمن. قد يكون القرار صغيراً لكنه مؤثر إذا غيّر طريقة التعامل مع التحدي، وقد يكون واسعاً ظاهرياً لكنه شكلي إذا أعاد اللاعب إلى النتيجة نفسها دون أثر محسوس.

حلّل ثلاثة عناصر: وضوح البدائل، قابلية توقع العواقب، وظهور أثر القرار لاحقاً. لا يشترط أن تكون كل النتائج مختلفة جذرياً؛ يكفي أن يشعر اللاعب أن قراره غيّر علاقة أو مورداً أو مخاطرة أو زاوية فهم. وفي المقابل، لا تعتبر الغموض عيباً تلقائياً؛ قد يكون جزءاً من تجربة أخلاقية أو استكشافية، لكن ينبغي أن يكون مقصوداً ومفهوماً ضمن قواعد العمل.

لا تستنتج فاعلية اللاعب من وصف المتجر أو قائمة الميزات. تحتاج إلى تجربة مباشرة أو مراجعات موثوقة تصف قرارات محددة. عند غيابها، اشرح ما تعلنه اللعبة فقط وامتنع عن ادعاء اختبار نتائج لم تتحقق منها.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('game-difficulty-fairness','الصعوبة والإنصاف: التحدي الذي يعلّم لا يعاقب اعتباطاً','game','difficulty',96,'قيّم الصعوبة عبر وضوح القواعد واتساق العقوبة وفرص التعلم، لا عبر وصف اللعبة بأنها سهلة أو قاسية فقط.','اسأل هل يفهم اللاعب سبب الفشل؟ هل تمنحه اللعبة فرصة لتعديل الاستراتيجية؟ هل تتناسب العقوبة مع الخطأ؟ فرّق بين تحدٍ مرتفع وتصميم غير منصف.','الصعوبة ليست رقماً منفرداً، بل علاقة بين متطلبات اللعبة وقدرة اللاعب على فهمها والاستجابة لها. التحدي الجيد قد يكون قاسياً، لكنه يكشف قواعده تدريجياً ويمنح اللاعب فرصة لتحويل الفشل إلى معرفة. أما العقوبة الاعتباطية فتظهر عندما لا يستطيع اللاعب فهم سبب الخسارة أو عندما تتغير القواعد دون تمهيد.

افحص وضوح الإشارات، واتساق سلوك الخصوم، وسرعة إعادة المحاولة، وكلفة الفشل، وتدرج التعلم. لا يعني تكرار المحاولة أن التصميم سيئ؛ المهم هل تتغير معرفة اللاعب أو خطته بين محاولة وأخرى؟ ولا يعني سهولة البداية أن اللعبة سطحية؛ فقد يكون منحنى التعلم متدرجاً عمداً.

تجنب مساواة الصعوبة بالجودة أو استخدام تجربة لاعب واحد لتعميم حكم مطلق. اذكر نمط اللعب ومستوى الخبرة عندما يكونان مؤثرين، وميّز بين خلل تقني موثق وبين قرار تصميمي لا يوافق ذوقك. لا تدّع اختبار التوازن دون مادة لعب أو أدلة نقدية مباشرة.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('game-level-design','تصميم المراحل: التوجيه والاستكشاف وتوزيع المخاطر','game','level-design',94,'حلّل كيف تقود المساحة اللاعب وتوازن بين الوضوح والاكتشاف، وكيف تتحول البيئة إلى جزء من التحدي والسرد.','اسأل كيف يتعلم اللاعب قراءة المكان؟ هل تكشف المعالم الاتجاهات؟ هل تخدم المسارات أساليب مختلفة؟ لا تخلط اتساع الخريطة بعمق تصميمها.','المستوى الجيد لا يُقاس بمساحته، بل بما يتيحه من قرارات ومعلومات وإيقاع. البيئة توجه اللاعب عبر التكوين والمعالم والإضاءة وتوزيع المخاطر والمكافآت. قد يكون المسار الخطي غنياً إذا كشف تحدياته بترتيب ذكي، وقد تكون الخريطة المفتوحة فارغة إذا لم تمنح الاستكشاف غرضاً أو اكتشافاً ذا قيمة.

اختبر العلاقة بين التوجيه والحرية. هل يستطيع اللاعب استنتاج الوجهة دون أن يفقد فرصة الانحراف؟ هل تكافئ المسارات البديلة الفضول أو تقدم زاوية لعب مختلفة؟ هل تتغير المساحة بعد حدث أو قدرة جديدة؟ انظر أيضاً إلى الإيقاع المكاني: التناوب بين الضغط والهدوء، وبين المواجهة والاستكشاف، قد يصنع توتراً أكثر فاعلية من زيادة الأعداء باستمرار.

لا تستنتج جودة تصميم المراحل من صور الخريطة أو حجم العالم وحدهما. تحتاج الأحكام عن تدفق اللعب والقراءة المكانية إلى تجربة أو تحليل موثوق. اربط كل ملاحظة بمثال محدد، ولا تصف مناطق لم تثبت زيارتها.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('game-progression-economy','التقدم والاقتصاد: قيمة المكافأة وكلفة التطوير','game','progression',92,'افحص ما إذا كان التقدم يفتح قرارات جديدة أم يرفع الأرقام فقط، وهل تحترم المكافآت وقت اللاعب.','حلّل مصادر الموارد وكلفة الإنفاق وأثر الترقيات. هل يغيّر التطوير أسلوب اللعب؟ هل توجد اختيارات ذات مفاضلة؟ لا تفترض أن كثرة المحتوى تعني تقدماً جيداً.','أنظمة التقدم تنظم علاقة الوقت بالمكافأة. لا يكفي أن يحصل اللاعب على نقاط أو معدات باستمرار؛ السؤال هل تفتح المكافأة إمكانية جديدة أم تزيد رقماً بلا تغيير في القرارات؟ الترقية المؤثرة توسع الخيارات أو تعيد تعريف أسلوب اللعب، بينما قد يتحول التقدم إلى عمل روتيني إذا كان المطلوب تكرار النشاط نفسه للوصول إلى زيادة محدودة.

افحص مصادر الموارد، وتكلفة الشراء، ووضوح قيمة العناصر، وإمكانية إعادة توزيع النقاط، ومدى وجود مفاضلات حقيقية. الاقتصاد المتوازن لا يعني أن يحصل اللاعب على كل شيء بسهولة، بل أن يفهم لماذا يدخر أو ينفق وما الذي يخسره مقابل اختياره. انتبه أيضاً إلى أنظمة الوقت والانتظار والشراء الإضافي، لكن لا تصفها بأنها استغلالية دون دليل على تصميمها وسياقها.

لا تحكم على الاقتصاد من قائمة العناصر أو وصف التحديثات فقط. يلزم توثيق مسار التقدم وتجربة فعلية أو مراجعات مفصلة. افصل بين رأيك في وتيرة المكافآت وبين الادعاء بأن النظام يفرض دفع المال أو يعرقل التقدم.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('movie-theme-subtext','الثيمة والمعنى الضمني: ما يقوله العمل عبر اختياراته','movie','theme',93,'حلّل الثيمة من تكرار القرارات والتناقضات والعواقب، لا من استخراج رسالة جاهزة أو نسبة نية مؤكدة لصانع العمل.','لا تختزل الفيلم في شعار أخلاقي. ابحث عن الفكرة التي تتكرر عبر الأفعال والعواقب، وميّز بين ما يقوله العمل صراحة وما تسمح بنيته بتأويله.','الثيمة ليست جملة يمكن إلصاقها بالفيلم بعد مشاهدته، بل نمط من الأسئلة والتوترات يظهر عبر الشخصيات والقرارات والصور والنهاية. قد يعلن الحوار فكرة، بينما تكشف الأفعال تناقضاً معها؛ وقد يترك العمل أكثر من احتمال دون أن يحسم موقفاً واحداً.

ابحث عن التكرار والتحول: ما المعضلة التي تعود بأشكال مختلفة؟ من يدفع ثمن القرار؟ هل تمنح الحبكة الفكرة تعقيداً أم تستخدم الشخصيات لتأكيد درس مباشر؟ لا تجعل كل تفصيل رمزاً، ولا تفترض أن اللون أو الشيء يحمل معنى ثابتاً. التأويل الأقوى يشرح لماذا تدعمه عدة لحظات أو اختيارات بنيوية.

ميّز بين قراءة المتلقي ونية المخرج أو الكاتب. يمكنك القول إن بنية الفيلم تتيح قراءة معينة، لكن لا تنسب قصداً مؤكداً إلى صانعه دون تصريح موثوق. لا تحرق النهاية بلا ضرورة؛ اشرح وظيفة التحول بصورة تحافظ على تجربة القارئ. وإذا كانت الأدلة المتاحة مجرد ملخص أو إعلان، فلا تدّع تحليل ثيمات التنفيذ الفعلي.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('movie-adaptation','الاقتباس والتحويل: من النص الأصلي إلى لغة الشاشة','movie','adaptation',91,'قيّم الاقتباس باعتباره إعادة بناء بوسيط مختلف، لا اختباراً لمدى التطابق الحرفي مع المصدر.','اسأل ما الذي احتفظ به الاقتباس وما الذي غيّره ولماذا يخدم الوسيط الجديد. لا تعتبر الحذف خيانة تلقائية ولا التغيير نجاحاً تلقائياً.','الاقتباس ليس نسخة مصورة من مادة سابقة؛ إنه انتقال بين وسائط لها إمكانات وحدود مختلفة. الرواية قد تعتمد على الصوت الداخلي والتفصيل والوصف، بينما تحتاج الشاشة إلى صورة وأداء وصوت وزمن محدد. لذلك يكون السؤال النقدي: كيف أعاد العمل تنظيم المادة كي تصبح درامية أو بصرية أو سمعية؟

افحص ما احتفظ به، وما اختصره، وما أعاد ترتيبه، وما أضافه. لا تحكم على التغيير بأنه خطأ لمجرد اختلافه عن الأصل؛ اسأل هل خلق منطقاً متماسكاً داخل الفيلم؟ وفي المقابل، لا تبرر كل تغيير بضرورة الوسيط إذا أضعف الدوافع أو قطع السببية أو أفرغ العلاقات من معناها. قارن الوظيفة لا التفاصيل فقط: هل يؤدي المشهد الجديد دوراً مماثلاً، أم يغير معنى الشخصية أو الصراع؟

تحتاج المقارنة إلى معرفة موثوقة بالمصدر الأصلي وبالفيلم. إذا لم تتوفر قراءة أو مشاهدة كافية للمادة الأصلية، لا تصدر حكماً شاملاً على الأمانة أو الخيانة. صرّح بنطاق المقارنة، وافصل تقييم الفيلم كعمل مستقل عن تقييم علاقته بمصدره.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('movie-ending','النهايات: الوفاء بالوعد الدرامي وترك الأثر','movie','ending',90,'اختبر النهاية بقدرتها على إكمال التحولات والأسئلة التي زرعها العمل، لا بمدى صدمتها أو إرضائها للجمهور.','اسأل هل تنبع النهاية من اختيارات سابقة؟ هل تحسم ما وعد به العمل؟ هل الغموض مقصود ومهيأ؟ لا تساوِ بين النهاية المفتوحة والنهاية الناقصة.','النهاية ليست مفاجأة أخيرة فحسب؛ إنها اللحظة التي يعاد فيها وزن القرارات السابقة. النهاية المتماسكة تنبع من الصراع الذي بناه العمل، وتمنح التحولات ثمناً أو نتيجة، حتى عندما تترك بعض الأسئلة مفتوحة. أما المفاجأة التي لا تستند إلى تمهيد فقد تصدم لحظياً لكنها تضعف العلاقة بين السبب والنتيجة.

قيّم الوفاء بالوعد الدرامي: ما الأسئلة التي جعلها العمل مركزية؟ أيها أجاب عنه؟ وهل أجاب بطريقة تتفق مع الشخصيات وقواعد العالم؟ لا يشترط أن يغلق كل خط، فالغموض قد يكون اختياراً فنياً، لكن ينبغي أن يكون له أساس في الموضوع أو المنظور أو بنية السرد. كذلك لا تجعل رضاك الشخصي معياراً وحيداً؛ النهاية المحبطة قد تكون صادقة مع العمل، والنهاية السعيدة قد تكون مستحقة أو مصطنعة.

عند النقد العام تجنب كشف التفاصيل الحاسمة. وإذا احتجت إلى تحليل حرق الأحداث، فنبّه بوضوح. لا تصف نهاية عمل لم تتوفر عنها مادة كافية، ولا تستنتج نجاحها من تقييم الجمهور وحده.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('series-character-arcs','تطور الشخصيات عبر المواسم: التراكم والاستمرارية','tv','character-arcs',95,'حلّل هل يترك الزمن أثراً على الشخصيات والعلاقات، وهل تتطور التحولات من أحداث وقرارات سابقة.','تتبع نقطة البداية والقرارات والعواقب عبر المواسم. هل يتغير السلوك بصورة مقنعة؟ هل تعود الشخصية إلى نقطة الصفر بلا تفسير؟ لا تخلط طول المسار بعمقه.','ميزة المسلسل أنه يستطيع اختبار الشخصية على مدى طويل، لكن طول الظهور لا يضمن تطوراً. القوس المقنع يجعل التجارب تترك أثراً في السلوك والعلاقات وطريقة فهم الشخصية لنفسها. وقد يكون التراجع أو الانتكاس جزءاً من تطور واقعي إذا كان له سبب، لا إذا كان مجرد إعادة ضبط لبدء حبكة جديدة.

تتبع القرارات المفصلية وما نتج عنها. هل تتذكر الكتابة تاريخ الشخصية؟ هل تتغير علاقتها بالآخرين بسبب ما حدث؟ هل تتعارض رغباتها مع مبادئها بطريقة تكشف تناقضاً؟ افحص أيضاً التوازن بين التطور الفردي والجماعي: أحياناً يدفع مسار شخصية أخرى إلى التغير، وأحياناً تستهلك الخطوط الفرعية وقتاً دون أن تؤثر في البناء.

لا تختصر تطور الشخصية بكونها أصبحت أفضل أو أسوأ؛ المهم اتساق التحول وتعقيده. لا تدّع متابعة مواسم أو حلقات لم تتوفر عنها أدلة. عندما تكون المادة محدودة، حدد الموسم أو الفترة التي يغطيها الحكم ولا تعمم على السلسلة كلها.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('series-season-architecture','بناء الموسم: التصعيد والحلقات المحورية والخاتمة','tv','season-structure',93,'قيّم الموسم كوحدة درامية لها وعد وتصعيد ونتيجة، مع الانتباه إلى توزيع التطور بين الحلقات.','اسأل كيف يغيّر كل فصل حالة الصراع؟ هل تخدم الحلقات الهادئة التراكم؟ هل تأتي الذروة نتيجة تمهيد؟ لا تساوِ كثرة الأحداث بالتصعيد.','يمكن قراءة الموسم كوحدة لها سؤال أو صراع مركزي، حتى عندما يمتد المسلسل إلى مواسم أخرى. البناء المتماسك يوزع المعلومات والتحولات بحيث تتغير حالة الصراع مع الوقت. لا يلزم أن تكون كل حلقة صاخبة؛ قد تكون الحلقة الهادئة ضرورية لتثبيت نتيجة أو تعميق علاقة أو زرع تفصيل يعود لاحقاً.

افحص وظيفة الحلقات المحورية: هل تغير اتجاه الموسم؟ هل تكشف معلومة تعيد تفسير ما سبق؟ هل تأتي الذروة نتيجة قرارات تراكمت أم تعتمد على حل طارئ؟ انظر إلى الخطوط الفرعية أيضاً: هل تغذي السؤال المركزي أو تمنح الشخصيات أبعاداً، أم تتوقف ثم تعود دون أثر؟ النهاية الجيدة لا تحتاج إلى حسم كل شيء، لكنها ينبغي أن تمنح الموسم نتيجة محسوسة وتبرر استمرار القصة إن وجد.

لا تستنتج الحشو من عدد الحلقات أو مدتها فقط. يلزم تحليل أحداث الحلقات أو مصادر نقدية تفصيلية. حدد نطاق المشاهدة، ولا تصف موسماً كاملاً بناءً على ملخصات متفرقة.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('cross-genre-judgment','الإنصاف بين الأنواع: لا تحاكم الكوميديا بمعيار الرعب','all','genre-fairness',92,'طبّق معايير نقدية ثابتة مع تفسير اختلاف وظيفة كل نوع، ولا تجعل ذوقك الشخصي قانوناً عاماً.','اسأل ما الوعد الذي يقدمه النوع؟ هل ينجح العمل في تحقيقه؟ لا تقارن الرعب بالكوميديا أو اللعبة السردية بمحاكاة رياضية بمقياس واحد دون سياق.','الإنصاف النقدي لا يعني أن تكون كل الأعمال متشابهة، بل أن نستخدم أسئلة مناسبة لوظيفة كل عمل. الرعب قد ينجح في بناء الترقب والتهديد، والكوميديا في توقيت المفارقة وتماسك النبرة، والدراما في تعقيد الصراع، واللعبة التنافسية في وضوح القواعد والتوازن. لا يصح أن نعاقب عملاً لأنه لا يحاول أداء وظيفة لا ينتمي إليها.

ابدأ بتحديد الوعد النوعي الذي يقدمه العمل، ثم اختبر جودة التنفيذ ضمن هذا الوعد. لا تمنح النوع حصانة من النقد؛ فالرعب يمكن أن يفشل في خلق التوتر، والكوميديا قد تعتمد على نكات مكررة، والدراما قد تتصنع العمق. لكن لا تفرض على الكوميديا أن تكون مأساوية أو على لعبة أركيد أن تقدم سرداً سينمائياً.

افصل بين تفضيلك الشخصي ونجاح العمل في غايته. يمكنك ألا تحب نوعاً ما، لكن ينبغي أن تشرح ما إذا كان العمل متقناً ضمن قواعده. وعند المقارنة بين أنواع مختلفة، صرّح بمعايير المقارنة وحدودها بدلاً من ترتيبها كأنها تقيس الشيء نفسه.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('review-comparison-method','المقارنة النقدية: أوجه الشبه لا تعني تكافؤ الجودة','all','comparison',90,'قارن الأعمال عبر محور مشترك محدد، ولا تستنتج التأثير أو التفوق من تشابه النوع أو الطاقم.','حدد محور المقارنة أولاً: البناء أو الإيقاع أو الأنظمة أو الأسلوب. استخدم أمثلة من العملين، ولا تحول التشابه إلى ادعاء اقتباس أو تأثير.','المقارنة المفيدة لا تكتفي بقول إن عملين متشابهان أو إن أحدهما أفضل. يجب تحديد المحور الذي يجعلهما قابلين للمقارنة: طريقة بناء الشخصية، إدارة الزمن، تصميم مساحة اللعب، استخدام الصوت، أو علاقة العالم بالموضوع. بعد ذلك نبحث عن اختلافات محددة في الاختيارات والنتائج.

التشابه في النوع أو الممثل أو المطور لا يثبت تشابهاً فنياً، ولا يثبت أن عملاً أثّر في الآخر. ادعاء التأثير يحتاج إلى مصدر أو قرائن تاريخية، بينما يمكن وصف التقارب بوصفه ملاحظة تحليلية محدودة. تجنب أيضاً مقارنة عمل مكتمل بعمل لم يصدر أو لم تتوفر عنه أدلة كافية؛ المقارنة العادلة تتطلب نطاقاً متقارباً من المعرفة.

لا تستخدم مقارنة لتضخيم درجة عمل أو خفض درجة آخر. اشرح أين يتفوق كل عمل وأين يتعثر، وما إذا كان الاختلاف نابعاً من هدف فني مختلف. يجب أن تبقى النتيجة مرتبطة بالأمثلة لا بالحنين أو الشعبية أو مكانة الاسم.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('evidence-hierarchy','هرم الأدلة: كيف نزن المصدر قبل استخدام المعلومة','all','research',99,'صنّف المصادر حسب قربها من الادعاء واستقلالها وحداثتها، ولا تعامل البيانات التسويقية أو تقييمات الجمهور كأدلة نقدية على الجودة.','قبل استخدام أي معلومة اسأل: من نشرها؟ هل هو مصدر أولي؟ هل تؤيد الادعاء المحدد؟ هل يوجد تأكيد مستقل؟ افصل بيانات الفهرسة عن التحليل النقدي.','ليست كل الروابط دليلاً على كل شيء. صفحة رسمية قد تكون مصدراً جيداً لتاريخ الإصدار أو أسماء الطاقم، لكنها ليست حكماً مستقلاً على جودة العمل. قاعدة بيانات قد تساعد في التحقق من المدة أو التصنيف، لكنها لا تثبت أن الإيقاع ناجح. مراجعة نقدية قد تقدم ملاحظة عن الأداء أو المونتاج، لكنها تظل رأياً يحتاج إلى نسبة واضحة وسياق.

قيّم المصدر بأربعة أسئلة: قربه من المعلومة، استقلاله، حداثته، ووضوح منهجه. المصدر الأولي مناسب للحقائق التي يعلنها صاحبه، والمصدر المستقل مهم للتحقق من الادعاءات المتنازع عليها أو لتقديم تحليل. تكرار الخبر نفسه في مواقع تنقل عن بعضها لا يصنع تعدد مصادر حقيقياً. كذلك لا تخلط بين عدد الأصوات والتوافق النقدي.

اربط كل مصدر بالادعاء الذي يدعمه تحديداً. إذا اختلفت المصادر، سجّل التعارض ولا تنتقِ الرقم الذي يناسب النتيجة. لا تملأ الفراغ بتخمين، ولا ترفع معلومة تسويقية إلى حقيقة مستقلة. وعندما لا يتوفر دليل كافٍ، قل ذلك بوضوح ثم ضيّق نطاق الحكم.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('score-calibration-bands','معايرة الدرجات: معنى كل نقطة ومنع التضخم','all','scoring-calibration',100,'اجعل لكل نطاق معنى نقدياً ثابتاً، واطلب من الدرجة العالية دليلاً أقوى من مجرد غياب العيوب.','استخدم 5 كنقطة وسط لا كإهانة، وميّز بين الإتقان الجيد والتميز الاستثنائي. لا تمنح 9 أو أكثر إلا مع تفوق واضح ومتكرر ومسنود بأمثلة.','الدرجة من عشرة ليست مقياساً لمدى حب الناقد للعمل، بل اختصار لحكم تحليلي. يجب أن يحمل كل نطاق معنى ثابتاً عبر الأعمال والأنواع، مع مراعاة اختلاف وظيفة المحاور. الدرجة حول الوسط تعني نجاحاً جزئياً أو تجربة مختلطة، وليست حكماً بأن العمل سيئ. الدرجات المرتفعة تتطلب اتساقاً وتميزاً واضحين، والدرجات المنخفضة تتطلب تحديد خلل جوهري لا مجرد اختلاف ذوق.

لا تجعل 7 هي الدرجة الافتراضية لكل عمل مشهور، ولا تستخدم 9 لمكافأة الطموح أو الإنتاج الضخم. الدرجة 9 وما فوق ينبغي أن تكون نادرة، وأن يشرح النص لماذا يتجاوز العمل مستوى الإتقان الجيد: ابتكار مؤثر، تنفيذ استثنائي، تماسك نادر، أو أثر واضح في محوره. وبالمثل، لا تخفض محوراً لأن معلوماته ناقصة؛ إذا غاب الدليل فالحكم محدود، لا سلبي تلقائياً.

قيّم المحاور بشكل مستقل ثم طبّق الأوزان المتفق عليها: القصة 30%، الصورة 25%، الصوت 20%، الإيقاع 25%. راجع اتساق الدرجة مع الأدلة المكتوبة، واحسب المتوسط الموزون دون تعديل يدوي لإرضاء الانطباع. الدرجة النهائية لا ينبغي أن تتجاوز ما تثبته المحاور.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('review-voice-and-originality','الصوت التحريري: موقف واضح دون استعراض أو تقليد','all','voice',88,'ابنِ صوتاً نقدياً مستقلاً عبر دقة الملاحظة وترابط الحجة، لا عبر المبالغة أو استعارة أسلوب ناقد آخر.','اكتب أطروحة تخص هذا العمل، وادعمها بتفاصيل، ووازن بين القوة والقصور. تجنب الجمل الدعائية والعبارات الجاهزة واليقين المصطنع.','الصوت النقدي لا يتكون من كثرة الصفات أو الجمل الحادة، بل من طريقة اختيار السؤال وربط التفاصيل بالنتيجة. ينبغي أن يستطيع القارئ فهم موقف الناقد حتى عندما يختلف معه، لأن الحجة واضحة ومسنودة. الأطروحة الجيدة تخص العمل: لا يمكن نقلها كما هي إلى أي فيلم أو لعبة أخرى دون أن تفقد معناها.

تجنب المديح التسويقي مثل تجربة لا تنسى أو تحفة مطلقة ما لم تشرح بدقة ما الذي يجعلها كذلك. وتجنب السلبية الاستعراضية التي تصنع عيوباً لإظهار الصرامة. لا تقلّد بنية ناقد معروف أو عباراته؛ تعلم من وضوح الحجة وتوازنها، ثم اكتب بصياغة أصلية. نوّع الإيقاع اللغوي، واجعل كل فقرة تضيف فكرة أو دليلاً أو نتيجة.

لا تخلط بين الثقة واليقين. استخدم لغة حاسمة عندما تكون الأدلة قوية، ولغة محدودة عندما تكون القراءة احتمالية. لا تخترع اقتباساً أو مشهداً أو تجربة شخصية. المصداقية تأتي من أن يعرف القارئ أين ينتهي الدليل وأين يبدأ التأويل.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('review-limitations','القيود والعيوب: النقد المحدد لا قائمة الشكاوى','all','limitations',89,'اكتب العيوب بوصفها آثاراً محددة على التجربة، ولا تكرر تحفظاً واحداً بصيغ متعددة أو تخلق عيباً لموازنة المديح.','لكل تحفظ اشرح موضعه وأثره وحدوده. فرّق بين خلل موضوعي وتفضيل شخصي، ولا تعتبر غياب ميزة تحبها عيباً عاماً.','قائمة السلبيات ليست شرطاً شكلياً يفرض على الناقد اختراع عيبين لكل عمل. قد يكون العمل متماسكاً مع تحفظات طفيفة، وقد تتراكم مشكلاته حول محور واحد. المطلوب هو الدقة لا التوازن الحسابي. اشرح ما الذي يضعف التجربة، وأين يظهر، ومن قد يتأثر به، وهل يتكرر أم يقتصر على حالة محددة.

فرّق بين العيب والتفضيل. غياب العالم المفتوح ليس نقصاً في لعبة خطية، وقلة الموسيقى ليست مشكلة في فيلم يعتمد الصمت، والنهاية المفتوحة ليست فشلاً تلقائياً. يصبح الأمر قصوراً عندما يتعارض مع هدف العمل أو يضعف وضوحه أو يقطع سببيته أو يكرر تجربة لا تضيف جديداً.

لا تكرر الفكرة نفسها في أكثر من نقطة، ولا تحول احتمالاً إلى حقيقة. إذا كان التحفظ مبنياً على ذوق شخصي، صرّح بذلك. وإذا لم تجد دليلاً على خلل محدد، لا تضف سلبية لمجرد إكمال القائمة؛ يمكن أن تذكر حدود التقييم أو أن العمل لا يقدم مشكلة جوهرية واضحة ضمن نطاق الأدلة.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('series-finale-and-closure','خاتمة المسلسل: الإغلاق والامتداد وذاكرة المشاهد','tv','finale',91,'اختبر هل تحترم الخاتمة تراكم الشخصيات والموضوعات، وهل تغلق الوعد الأساسي دون حل كل تفصيل بالضرورة.','قيّم النهاية في ضوء مسار السلسلة لا الحلقة الأخيرة وحدها. هل تنبع التحولات من التراكم؟ هل تمنح الخطوط الأساسية نتيجة؟ لا تجعل رضا الجمهور معياراً وحيداً.','خاتمة المسلسل تواجه عبئاً مختلفاً عن نهاية فيلم؛ عليها أن تتعامل مع تراكم مواسم وشخصيات وأسئلة طويلة. لا يلزم أن تحسم كل تفصيل، لكن ينبغي أن تمنح المسارات المركزية نتيجة تتناسب مع الوعود التي قطعتها السلسلة. قد يكون ترك بعض الأبواب مفتوحة منطقياً إذا كان موضوع العمل عن الاستمرار أو عدم اليقين، وقد يبدو هروباً إذا تجاهل صراعاً ظل محورياً.

افحص ما إذا كانت التحولات الأخيرة نابعة من تاريخ الشخصيات، وهل تحافظ الخاتمة على نبرة العالم وقواعده. هل تحصل الشخصيات على نتائج تتناسب مع اختياراتها؟ هل تعود موضوعات البداية بصورة جديدة؟ وهل تمنح الحلقة الأخيرة وزناً للحلقات السابقة أم تحاول حل كل شيء عبر مصادفات سريعة؟

افصل بين جودة البناء ورضا الجمهور. يمكن أن تكون النهاية مؤلمة لكنها متماسكة، أو مرضية لكنها متعجلة. لا تختزل الحكم في الشعبية أو ردود الفعل الأولى. وحدد ما إذا كنت تقيم الحلقة الأخيرة أم السلسلة كاملة، لأنهما نطاقان مختلفان.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('accessibility-and-usability','إمكانية الوصول وسهولة الاستخدام: التصميم لمن يلعب','game','accessibility',87,'قيّم وضوح الواجهة وخيارات الوصول وقابلية تخصيص التحكم، مع تجنب افتراض أن خياراً واحداً يناسب الجميع.','افحص قراءة النصوص، وإعادة تعيين الأزرار، وخيارات الصعوبة والإشارات السمعية والبصرية. لا تفترض توفر ميزة أو غيابها دون توثيق.','سهولة الاستخدام ليست مسألة ذوق ثانوي؛ إنها تحدد كيف يفهم اللاعب القواعد ويتفاعل معها. الواجهة الواضحة تقلل الاحتكاك غير الضروري وتترك التحدي داخل اللعب نفسه. أما خيارات الوصول فتتيح لشرائح مختلفة تعديل التجربة وفق احتياجاتها، ولا ينبغي اختزالها في وضع سهل أو اعتبارها تنازلاً عن التصميم.

افحص حجم النص والتباين، وإمكانية إعادة تعيين الأزرار، والتحكم في الحساسية والاهتزاز، والإشارات البصرية والسمعية، وخيارات تقليل الحركة أو الوميض، ووضوح القوائم. اسأل هل يمكن تخصيص المساعدة دون إزالة جوهر التحدي؟ وهل تعمل الخيارات باستمرار في القوائم واللعب والمشاهد؟ لا يوجد إعداد واحد مثالي للجميع، لذلك قيمة النظام في مرونته ووضوحه.

لا تدّع أن اللعبة تفتقر إلى ميزة وصول اعتماداً على مراجعة قديمة أو منصة مختلفة. تحقق من الإصدار والمنصة والتحديثات، وميّز بين وجود الخيار وجودة تطبيقه. إذا لم تتوفر قائمة موثوقة أو اختبار مباشر، صرّح بأن هذا الجانب لم يُتحقق منه.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('technical-stability','الأداء والاستقرار: الحكم على النسخة والمنصة لا السمعة','game','technical',97,'اربط أحكام الأداء بالمنصة والإصدار وظروف الاختبار، وافصل بين معدل الإطارات والدقة والاستقرار والأعطال.','لا تعمم من منصة إلى أخرى. اذكر الإصدار وظروف القياس عند توفرها، وميّز بين ملاحظة مراجعة وقياس تقني مستقل.','الأداء التقني ليس صفة مطلقة للعبة؛ قد يختلف باختلاف المنصة والإصدار والتحديثات ونمط العرض. لذلك لا يصح نقل نتيجة اختبار على جهاز إلى كل الأجهزة، ولا وصف اللعبة بأنها مستقرة اعتماداً على انطباع عام. يجب تحديد ما الذي نقيسه: معدل الإطارات، ثباته، زمن الاستجابة، الدقة، التحميل، الأعطال، أو جودة الصورة.

افصل بين الأرقام والملاحظة. قياس معدل الإطارات يحتاج إلى اختبار موثق وظروف قابلة للفهم، بينما وصف التقطيع أو التأخر يحتاج إلى تحديد السياق وتكراره. لا تخلط بين انخفاض الدقة ومشكلة الأداء، ولا بين عطل فردي وخلل واسع. التحديثات قد تغير النتيجة، لذلك يجب ذكر تاريخ أو إصدار الاختبار عندما يكون ذلك مهماً.

إذا لم تتوفر قياسات مستقلة أو تجربة مباشرة، لا تخترع أرقاماً ولا تكرر ادعاءات المنتديات كحقائق. يمكنك القول إن البيانات التقنية غير كافية للحكم. ولا تجعل الأداء وحده يحدد جودة اللعبة كلها؛ اشرح وزنه في التجربة والمنصة التي يهمها الحكم.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body,authoring,version,active) VALUES ('movie-genre-tone','النبرة والنوع: اتساق المزاج وتحوّلاته','movie','tone',86,'اختبر اتساق النبرة وتبرير الانتقال بين الكوميديا والدراما والتوتر، ولا تعتبر المزج النوعي عيباً تلقائياً.','حلّل هل الانتقالات النغمية ممهدة وتخدم الموضوع والشخصيات؟ هل يضعف المزج أثر المشاهد؟ لا تساوِ بين اختلاف النبرة وفقدان الهوية.','النبرة هي الإحساس الذي ينظم علاقة المشاهد بالعالم، وقد تتغير داخل العمل الواحد. المزج بين الكوميديا والدراما أو الرعب والسخرية ليس عيباً في ذاته؛ يصبح مشكلة عندما تبدو الانتقالات اعتباطية أو تقوض أثر المشهد دون أن تخلق معنى بديلاً.

راقب ما يمهد للتحول: أداء الشخصيات، والإيقاع، والموسيقى، وطريقة تصوير الحدث، والعواقب التي تليه. قد يخفف المزاح التوتر ليكشف هشاشة الشخصية، وقد يجعل التناقض المأساة أكثر قسوة. لكن إذا ألغت النكتة نتائج حدث خطير أو بدّل العمل قواعده العاطفية بلا سبب، فقد يفقد المتلقي ثقته بالنبرة.

لا تفرض نبرة واحدة على كل الأنواع، ولا تستخدم كلمة غير متوازن دون شرح. اذكر أين يحدث التحول وما أثره، وميّز بين قرار جمالي لا تفضله وبين تناقض يضعف البناء. يحتاج هذا الحكم إلى أمثلة من المشاهدة، لا إلى ملخص القصة وحده.','VibeCritic — manual editorial reference batch 0006',1,1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,authoring=excluded.authoring,version=excluded.version,active=1,updated_at=datetime('now');
